# Generated by Descant: acceptance tests.

require "spec_helper"

RSpec.describe "TimekeepingRules::EntryDecision" do
  # "An employee cannot create or edit a colleague's entry through user_id; an owner or admin can for a same-company user"
  it "refuses an employee naming a colleague by integer or string id and lets an admin name a same-company user" do
    decide = lambda do |role, requested|
      TimekeepingRules::EntryDecision.target_user(acting_user_id: 7, role:, requested_user_id: requested,
                                                  company_user_ids: [7, 8])
    end

    expect(decide.call("employee", 8)).to eq(:forbidden)
    expect(decide.call("employee", "8")).to eq(:forbidden)
    expect(decide.call("admin", "8")).to eq(:requested)
    expect(decide.call("owner", 8)).to eq(:requested)
    expect(decide.call("admin", 99)).to eq(:not_found)
    expect(decide.call("admin", "8; drop")).to eq(:not_found)
  end
end
